/**
 * Parse existing assignedJobs from shift data
 */
function parseAssignedJobs(shift) {
  if (!shift.assignedJobs) {
    return [];
  }

  if (typeof shift.assignedJobs === 'string') {
    try {
      return JSON.parse(shift.assignedJobs);
    } catch (e) {
      return [];
    }
  }

  if (Array.isArray(shift.assignedJobs)) {
    return [...shift.assignedJobs];
  }

  return [];
}

/**
 * Create an assigned job object from a match
 */
function createAssignedJob(match, traderName) {
  // Check if this trader is assigned as first half trader
  const isFirstHalfTrader = match['1st Half'] === traderName || match.firstHalf === traderName;

  return {
    type: isFirstHalfTrader ? 'FirstHalf' : match.betType,
    start: match.matchDate,
    end: match.endDate
  };
}

/**
 * Check if match starts during or after shift start
 */
function matchStartsAfterShift(shift, match) {
  const shiftStart = new Date(shift.startTime);
  const matchStart = new Date(match.matchDate);

  // Match must start at or after shift start
  return shiftStart <= matchStart;
}

/**
 * Find matches for a trader that start at or after shift start
 */
function findTraderMatchesInShift(matches, traderName, shift) {
  return matches.filter(match => {
    const isTraderMatch = match.hdpTrader === traderName ||
      match.ouTrader === traderName ||
      match['1st Half'] === traderName ||
      match.firstHalf === traderName;
    const matchStartsInShift = matchStartsAfterShift(shift, match);
    return isTraderMatch && matchStartsInShift;
  });
}

// Main execution
const allItems = $input.all();

// Get config
const configItem = allItems.find(item => item.json.nodeType === 'config');
const mjIncludeBettype = configItem?.json.mjIncludeBettype || [];

// Filter Major unchanged matches (for enrichment)
const matchesToConsider = allItems
  .filter(item => {
    if (item.json.nodeType !== 'mismatch') {
      return false;
    }

    // If mjIncludeBettype is configured, filter by betType
    if (mjIncludeBettype.length > 0) {
      const betType = (item.json.betType || '').toUpperCase();
      return mjIncludeBettype.some(includedBettype => includedBettype.toUpperCase() === betType);
    }

    // If no config, default to MJ only
    return item.json.betType === 'MJ' && item.json.isUnchanged;
  })
  .sort((a, b) => {
    const dateA = new Date(a.json.matchDate);
    const dateB = new Date(b.json.matchDate);
    return dateA - dateB; // ascending order
  });

// Process all items - enrich working shifts, pass through others
const enrichedItems = allItems.map(item => {
  // Only enrich working shifts
  if (item.json.nodeType === 'workingShift') {
    const shift = item.json;
    let assignedJobs = parseAssignedJobs(shift);

    // Find all MJ unchanged matches for this trader that start at or after shift start
    const traderMatches = findTraderMatchesInShift(
      matchesToConsider.map(m => m.json),
      shift.traderName,
      shift
    );

    // Append matched jobs to assignedJobs
    for (const match of traderMatches) {
      const job = createAssignedJob(match, shift.traderName);
      assignedJobs.push(job);
    }

    // Return enriched working shift
    return {
      json: {
        ...shift,
        assignedJobs: assignedJobs,
        nodeType: 'workingShift'
      },
      pairedItem: item.pairedItem
    };
  }

  // Pass through all other items unchanged
  return item;
});

return enrichedItems;

/**
 * Transform n8n data to Trader Assignment API format
 *
 * This code node transforms the input data from three different node types:
 * - mismatch (matches to assign)
 * - workingShift (trader availability)
 * - pairTrader (preconfigured trader pairs)
 *
 * Into the API format with proper field mappings and skill parsing.
 */

const allItems = $input.all();

/**
 * Parse bettype string into skills array (HDP and/or OU only)
 *
 * Rules:
 * - "2" means trader can handle BOTH HDP and OU
 * - "2[OP]" is ignored (not relevant for MJ assignment)
 * - "R-FS" is ignored (not relevant for MJ assignment)
 * - Only HDP and OU skills are extracted
 *
 * Examples:
 * - "HDP/M1*2" → ["HDP"]
 * - "OU/M1*2" → ["OU"]
 * - "2/M1*2" → ["HDP", "OU"]
 * - "2[OP]" → []
 * - "OU/R-FS/M1*2" → ["OU"]
 */
function parseBetTypeToSkills(bettype) {
  if (!bettype) return [];

  const parts = bettype.split('/');
  const skills = new Set();

  for (const part of parts) {
    const trimmed = part.trim();

    // Skip multiplier patterns (M1*2, M2*1, etc.)
    if (trimmed.match(/^M\d+\*\d+/)) continue;

    // Skip irrelevant skills
    if (trimmed.startsWith('2[OP]') || trimmed.startsWith('R-FS')) continue;

    // "2" means can handle both HDP and OU
    if (trimmed === '2' || trimmed.startsWith('2 ')) {
      skills.add('HDP');
      skills.add('OU');
    }
    // Direct HDP or OU
    else if (trimmed.startsWith('HDP')) {
      skills.add('HDP');
    }
    else if (trimmed.startsWith('OU')) {
      skills.add('OU');
    }
    // Handle patterns like "Solo HDP", "Priority HDP"
    else if (trimmed.match(/^[A-Z]/)) {
      if (trimmed.includes('HDP')) skills.add('HDP');
      if (trimmed.includes('OU')) skills.add('OU');
    }
  }

  return Array.from(skills);
}

/**
 * Capitalize first letter of a string
 * Used for level transformation: "elite" → "Elite", "first" → "First"
 */
function capitalizeFirst(str) {
  if (!str) return str;
  return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
}

// Initialize result arrays
const matches = [];
const traderShifts = [];
const preconfiguredPairs = [];

// Define transformation handlers for each nodeType
const nodeTypeHandlers = {
  mismatch: (data) => {
    // Only include MJ matches
    if (data.betType === 'MJ') {
      matches.push({
        id: data.rowNumber?.toString() || '',
        matchNo: data.no?.toString() || '',
        start: data.matchDate,
        end: data.endDate,
        maxBet: data.maxBet || 0,
        leagueCode: data.leagueCode || null,
        leagueName: data.league || null,
        betType: data.betType || null,
        isSoloMatch: data.isSoloMatch || false,
        isAlreadyHandled: data.isUnchanged || false,
        isEXPT: data.isEXPT !== undefined ? data.isEXPT : true,
        isEAL: data.isEAL || false,
        isUseAlternativeMJRule: data.isUseAlternativeMJRule || false
      });
    }
  },

  workingShift: (data) => {
    traderShifts.push({
      id: data.rowNumber?.toString() || '',
      name: data.traderName || '',
      start: data.startTime,
      end: data.endTime,
      skills: parseBetTypeToSkills(data.bettype),
      level: capitalizeFirst(data.staffLevel),
      isManager: data.isManager || false,
      isEXPTMatchAssignable: data.isEXPTAssignable !== undefined ? data.isEXPTAssignable : true,
      ignoreLeague: data.ignoreLeague || [],
      nonSoloLeagues: data.nonSoloLeague || [],
      priorityLeagues: data.priorityLeague || [],
      maxBet: data.maxBet !== undefined ? data.maxBet : 1000000, // Default: 1 million (no limit)
      prioritySkill: data.prioritySkill || null,
      assignedJobs: data.assignedJobs?.map(job => ({
        type: job.type,
        start: job.start,
        end: job.end
      })) || []
    });
  },

  pairTrader: (data) => {
    preconfiguredPairs.push({
      hdp: data.hdp,
      ou: data.ou,
      tier: data.tier,
      leaguePriority: data.league_priority || {}
    });
  }
};

// Process each item using the appropriate handler
for (const item of allItems) {
  const data = item.json;
  const handler = nodeTypeHandlers[data.nodeType];

  if (handler) {
    handler(data);
  }
}

// Return transformed data in API format
return [{
  json: {
    traderShifts: traderShifts,
    matches: matches,
    preconfiguredPairs: preconfiguredPairs
  }
}];

// Code-based League Code Detection
// Replaces AI-based detection with a mapping approach

const input = $input.all();

// Extract matches and pair configurations from input
const matches = [];
const pairConfig = [];

for (const item of input) {
  const data = item.json;

  // Check if this is a Major match (betType = MJ)
  if (data.nodeType === 'mismatch' && data.betType === 'MJ') {
    matches.push({
      rowNumber: data.rowNumber,
      matchNo: data.no,
      league: data.league,
      start: data.matchDate,
      end: data.endDate
    });
  }

  // Check if this is pair trader config
  else if (data.nodeType === 'pairTrader') {
    const leaguePriority = {
      '1st': null,
      '2nd': null,
      '3rd': null
    };

    // Extract league priorities from league_priority object
    if (data.league_priority) {
      if (data.league_priority[1] && Array.isArray(data.league_priority[1]) && data.league_priority[1].length > 0) {
        leaguePriority['1st'] = data.league_priority[1][0];
      }
      if (data.league_priority[2] && Array.isArray(data.league_priority[2]) && data.league_priority[2].length > 0) {
        leaguePriority['2nd'] = data.league_priority[2][0];
      }
      if (data.league_priority[3] && Array.isArray(data.league_priority[3]) && data.league_priority[3].length > 0) {
        leaguePriority['3rd'] = data.league_priority[3][0];
      }
    }

    pairConfig.push({
      hdp: data.hdp,
      ou: data.ou,
      tier: data.tier,
      '1st': leaguePriority['1st'],
      '2nd': leaguePriority['2nd'],
      '3rd': leaguePriority['3rd']
    });
  }
}

// Extract all unique league codes from pair configurations
const leagueCodesSet = new Set();

for (const config of pairConfig) {
  if (config['1st']) leagueCodesSet.add(config['1st']);
  if (config['2nd']) leagueCodesSet.add(config['2nd']);
  if (config['3rd']) leagueCodesSet.add(config['3rd']);
}

// Convert to sorted array
const availableLeagueCodes = Array.from(leagueCodesSet).sort();

/**
 * League name to code mapping
 * Maps common league name patterns to their standard codes
 * Only supports top 5 major European leagues
 */
const LEAGUE_MAPPINGS = {
  // English Premier League
  'EPL': [
    'ENGLISH PREMIER LEAGUE',
    'EPL',
    'PREMIER LEAGUE',
    'ENGLAND PREMIER LEAGUE',
    '*ENGLISH PREMIER LEAGUE'
  ],

  // Spanish La Liga
  'SPA': [
    'SPAIN PRIMERA LALIGA',
    'LA LIGA',
    'LALIGA',
    'SPAIN LA LIGA',
    'SPANISH PRIMERA',
    '*SPAIN PRIMERA LALIGA',
    'SPAIN PRIMERA DIVISION'
  ],

  // Italian Serie A
  'ITA': [
    'ITALY SERIE A',
    'SERIE A',
    'ITALIAN SERIE A',
    '*ITALY SERIE A',
    'ITALY SERIE-A'
  ],

  // German Bundesliga
  'GER': [
    'GERMANY-BUNDESLIGA I',
    'BUNDESLIGA',
    'GERMANY BUNDESLIGA',
    'GERMAN BUNDESLIGA',
    '*GERMANY-BUNDESLIGA I',
    'GERMANY BUNDESLIGA 1'
  ],

  // French Ligue 1
  'FRA': [
    'FRANCE LIGUE 1',
    'LIGUE 1',
    'FRENCH LIGUE 1',
    '*FRANCE LIGUE 1',
    'FRANCE LIGUE-1'
  ],

  // Japan J-League Division 1
  'JPN': [
    'JAPAN J-LEAGUE DIVISION 1',
    'JAPAN J-LEAGUE',
    'J-LEAGUE DIVISION 1',
    'J-LEAGUE',
    'JAPAN J1 LEAGUE',
    '*JAPAN J-LEAGUE DIVISION 1'
  ],

  // Australia A-League
  'AUS': [
    'AUSTRALIA A-LEAGUE',
    'A-LEAGUE',
    'AUSTRALIAN A-LEAGUE',
    '*AUSTRALIA A-LEAGUE',
    'AUSTRALIA A LEAGUE'
  ]
};

/**
 * Normalize league name for comparison
 * Removes special characters, extra spaces, and converts to uppercase
 */
function normalizeLeagueName(name) {
  if (!name) return '';

  return name
    .toUpperCase()
    .replace(/[^\w\s-]/g, ' ')  // Replace special chars with space
    .replace(/\s+/g, ' ')        // Collapse multiple spaces
    .trim();
}

/**
 * Match league name to league code
 * Returns the matching code or null if no match found
 */
function matchLeagueCode(leagueName, availableCodes) {
  if (!leagueName) return null;

  const normalized = normalizeLeagueName(leagueName);

  // First, try exact match with available codes (for efficiency)
  for (const code of availableCodes) {
    const patterns = LEAGUE_MAPPINGS[code];
    if (patterns) {
      for (const pattern of patterns) {
        const normalizedPattern = normalizeLeagueName(pattern);

        // Check for exact match
        if (normalized === normalizedPattern) {
          return code;
        }

        // Check if league name contains the pattern (for cases like "*ITALY SERIE A" in data)
        if (normalized.includes(normalizedPattern) || normalizedPattern.includes(normalized)) {
          return code;
        }
      }
    }
  }

  // Second pass: Try all mappings even if not in available codes
  // This helps catch leagues that should be mapped but aren't in pair config yet
  for (const [code, patterns] of Object.entries(LEAGUE_MAPPINGS)) {
    for (const pattern of patterns) {
      const normalizedPattern = normalizeLeagueName(pattern);

      if (normalized === normalizedPattern ||
          normalized.includes(normalizedPattern) ||
          normalizedPattern.includes(normalized)) {
        return code;
      }
    }
  }

  // No match found
  return null;
}

/**
 * Detect league codes for all matches
 */
const matchLeagueDetections = matches.map(match => {
  const leagueCode = matchLeagueCode(match.league, availableLeagueCodes);

  return {
    matchNo: match.matchNo,
    leagueName: match.league,
    leagueCode: leagueCode
  };
});

// Return result in the same format as AI node output
return [{
  json: {
    matchLeagueDetections: matchLeagueDetections
  }
}];
